#include <bits/stdc++.h>
using namespace std;
#define ll long long int

int main() {
	// your code goes here
    
    int t;
    cin>>t;
    while(t--)
    {
        ll n;
        cin>>n;
        ll m=3*n;
        vector<ll>vec(m+1);
        for(ll i=0;i<m;i++)
        cin>>vec[i];
        
        sort(vec.rbegin(),vec.rend());
        vector<ll>p(m+1,0);
        
        for(ll i=0;i<m;i++)
        p[i+1]=p[i]+vec[i];
        
        ll bestans=0;
        
        auto func = [&](ll a,ll b){
            
             ll vv = 2*p[a] + p[a+2*b] + 3*p[m-2*a-b] ;
             return vv;
        };
        
        for(ll i=0;i<=n;i++)
        {
            ll low=0,high=n-i;
            // ll ans=0;
            while(low<high)
            {
                ll mid=(low+high)/2;
                
                ll vv=vec[i+2*mid] - 3*vec[m-2*i-1-mid] + vec[i+2*mid+1];
                
                if(func(i,mid+1) > func(i,mid)){
                    
                    low=mid+1;
                }
                else
                high=mid;
            }
            
            bestans=max(bestans, func(i,low));
        }
        cout<<bestans<<endl;
    }
}
